//! Tables read by the native routines (`ddsom-game`) that the other files do not describe: `data/natives.json`.
//!
//! The zones come from a measurement (`native_zones.txt`, regenerated by `tools/native_zones.py` from the output of
//! `lectures_rom` in no-68000 mode over all the scenarios; docs/sans-rom.md): each line gives the space
//! (`d` data, `p` decrypted program), the start, the exclusive end and the Rust file that reads the zone. They are
//! small scattered tables (speeds, decisions, positions, strings, addresses of routines read by the dispatch
//! tables, interrupt vectors...) whose format is not yet described: they are stored as words
//! (or bytes if the zone is odd), under the name `<file>/<address>` (`prog/<file>/<address>` in program
//! space). A zone that a table of another
//! file already describes is not listed here.

use crate::data::{data, prog, Spec};

const ZONES: &str = include_str!("../native_zones.txt");

pub fn specs() -> Vec<Spec> {
    let mut s = Vec::new();
    for l in ZONES.lines().filter(|l| !l.starts_with('#') && !l.trim().is_empty()) {
        let t: Vec<&str> = l.split_whitespace().collect();
        let [space, start, end, reader] = t[..] else { panic!("native_zones.txt: unreadable line « {l} »") };
        let (start, end) = (u32::from_str_radix(start, 16).unwrap(), u32::from_str_radix(end, 16).unwrap());
        // the program space has its own names: the same address can be read in both spaces
        let name = if space == "p" { format!("prog/{reader}/{start:#x}") } else { format!("{reader}/{start:#x}") };
        let (format, rows) = if start % 2 == 0 && end % 2 == 0 { ("x16", (end - start) / 2) } else { ("u8", end - start) };
        s.push(match space {
            "d" => data(&name, start, format, &[], rows as usize),
            "p" => prog(&name, start, format, &[], rows as usize),
            _ => panic!("native_zones.txt: space « {space} »"),
        });
    }
    s
}
